import type {SyntheticClinicalCase,SyntheticClinicalRelease} from "./schema";
import type {QuestionShipAcceptance,QuestionShipManifest} from "./question-ship-manifest";

/** Resolve only explicit whole-case relations at the shipping projection.
 * No admission, frozen-save or scheduler path calls this function. */
export function resolveQuestionShipCaseReplacements(
  catalog:SyntheticClinicalRelease,legacy:SyntheticClinicalRelease,
  views:Readonly<Record<string,SyntheticClinicalRelease>>,manifest:QuestionShipManifest,
) {
  const issues:string[]=[],byLegacy=new Map<string,SyntheticClinicalCase>();
  const blockedLegacyIds=new Set<string>(),reservedTargetIds=new Set<string>();
  const concepts=new Set(catalog.concepts.map(c=>c.id));
  const index:Readonly<Record<string,SyntheticClinicalRelease>>={...views,catalog};
  const candidates:(
    {legacyCase:SyntheticClinicalCase;target:QuestionShipAcceptance;source:SyntheticClinicalCase;errors:string[]}
  )[]=[];
  for(const relation of manifest.replacements??[]){
    const old=legacy.cases.filter(cs=>cs.id===relation.replaces||cs.decisionNodes.some(n=>n.questionVariantId===relation.replaces));
    old.forEach(cs=>blockedLegacyIds.add(cs.id));
    const targets=manifest.accepted.filter(r=>r.questionVariantId===relation.with);
    targets.forEach(r=>reservedTargetIds.add(r.caseId));
    if(old.length!==1||targets.length!==1){
      issues.push(`replacement must identify one legacy case and one accepted exact draft: ${relation.replaces} -> ${relation.with}`);
      continue;
    }
    const target=targets[0]!,sourceCases=index[target.sourceView]?.cases.filter(cs=>cs.id===target.caseId)??[];
    if(sourceCases.length!==1){
      issues.push(`replacement has missing or duplicate source case: ${relation.with}`);
      continue;
    }
    const source=sourceCases[0]!,errors:string[]=[];
    if(source.id!==old[0]!.id&&legacy.cases.some(cs=>cs.id===source.id))errors.push("target would overwrite another legacy case");
    if(manifest.headerSources[source.id]!==target.sourceView)errors.push("header must use the exact replacement source view");
    const rows=manifest.accepted.filter(r=>r.caseId===source.id);
    const nodeIds=new Set(source.decisionNodes.map(n=>n.id));
    if(!source.decisionNodes.length||nodeIds.size!==source.decisionNodes.length)errors.push("empty or duplicate source nodes");
    if(rows.length!==source.decisionNodes.length)errors.push("whole source case must have exactly one acceptance for every node");
    for(const node of source.decisionNodes){
      const matching=rows.filter(r=>r.nodeId===node.id&&r.questionVariantId===node.questionVariantId&&
        r.conceptId===node.primaryConceptId&&r.sourceView===target.sourceView);
      if(matching.length!==1||!concepts.has(node.primaryConceptId))errors.push(`unaccepted or unknown source node/concept ${node.id}`);
    }
    candidates.push({legacyCase:old[0]!,target,source,errors});
  }
  for(const candidate of candidates){
    const {legacyCase,target,source,errors}=candidate;
    // Reject both sides of a conflicting relation, rather than keeping whichever
    // row happened to be encountered first.
    const oldRelations=(manifest.replacements??[]).filter(r=>r.replaces===legacyCase.id||legacyCase.decisionNodes.some(n=>n.questionVariantId===r.replaces));
    const targetRelations=(manifest.replacements??[]).filter(r=>r.with===target.questionVariantId);
    if(oldRelations.length!==1||targetRelations.length!==1||candidates.filter(c=>c.source.id===source.id).length!==1)
      errors.push("duplicate or conflicting replacement relation");
    if(errors.length)issues.push(`invalid replacement ${legacyCase.id} -> ${target.questionVariantId}: ${errors.join("; ")}`);
    else byLegacy.set(legacyCase.id,source);
  }
  return {issues,byLegacy,blockedLegacyIds,reservedTargetIds};
}

import type { SyntheticClinicalCase, SyntheticClinicalRelease } from "./schema";
import { QUESTION_SHIP_MANIFEST, type QuestionShipManifest } from "./question-ship-manifest";
import { resolveQuestionShipCaseReplacements } from "./question-ship-case-replacements";

/** The only runtime shipping boundary. Explicit catalogs remain usable.
 * Frozen encounters never pass through this projection. */
export function projectManagerAcceptedQuestions(
  catalog: SyntheticClinicalRelease,
  legacy: SyntheticClinicalRelease,
  views: Readonly<Record<string, SyntheticClinicalRelease>>,
  manifest: QuestionShipManifest = QUESTION_SHIP_MANIFEST,
): SyntheticClinicalRelease {
  // A source-view configuration error must not remove the legacy fallback.
  const legacyCases = new Map(legacy.cases.map(cs => [cs.id, cs]));
  const index = new Map(Object.entries({ ...views, catalog }).map(([name, release]) =>
    [name, new Map(release.cases.map(cs => [cs.id, cs]))]));
  const concepts = new Set(catalog.concepts.map(concept => concept.id));
  const replacements=resolveQuestionShipCaseReplacements(catalog,legacy,views,manifest);
  for(const issue of replacements.issues)
    console.warn(`[question-ship] ${issue}; retaining legacy case and omitting unverifiable replacement.`);
  const rows = new Map<string, QuestionShipManifest["accepted"][number][]>();
  for (const row of manifest.accepted) {
    rows.set(row.caseId, [...(rows.get(row.caseId) ?? []), row]);
  }
  const cases: SyntheticClinicalCase[] = [];
  for (const caseId of new Set([...legacyCases.keys(), ...rows.keys()])) {
    const fallback = legacyCases.get(caseId);
    const replacement=replacements.byLegacy.get(caseId);
    if(replacement){
      // Use the complete accepted source, including its node list. Never merge
      // retired neighbors into an explicitly approved one-node encounter.
      cases.push(replacement);
      continue;
    }
    if(replacements.blockedLegacyIds.has(caseId)||replacements.reservedTargetIds.has(caseId)){
      // Also prevents a malformed whole-case relation from silently becoming a
      // partial node override or an ordinary new-case acceptance.
      if(fallback)cases.push(fallback);
      continue;
    }
    const overrides = rows.get(caseId) ?? [];
    if (!overrides.length) {
      if (fallback) cases.push(fallback);
      continue;
    }
    const retainLegacy = (reason: string) => {
      console.warn(`[question-ship] ${caseId}: ${reason}; ${fallback ? "retaining legacy case" : "omitting new draft"}.`);
      if (fallback) cases.push(fallback);
    };
    if (new Set(overrides.map(row => row.nodeId)).size !== overrides.length) {
      retainLegacy("duplicate acceptance node");
      continue;
    }
    const headerView = manifest.headerSources[caseId] ?? "legacy";
    const header = index.get(headerView)?.get(caseId);
    if (!header) {
      retainLegacy(`missing case header in ${headerView}`);
      continue;
    }
    const baseNodes = fallback?.decisionNodes ?? header.decisionNodes;
    const nodeIds = new Set(baseNodes.map(node => node.id));
    if (nodeIds.size !== baseNodes.length ||
      new Set(header.decisionNodes.map(node => node.id)).size !== header.decisionNodes.length ||
      overrides.some(row => !nodeIds.has(row.nodeId)) ||
      (!fallback && baseNodes.some(node => !overrides.some(row => row.nodeId === node.id)))) {
      retainLegacy("duplicate, unknown or unaccepted case node");
      continue;
    }
    const nodes = [];
    let invalid = false;
    for (const node of baseNodes) {
      const row = overrides.find(row => row.nodeId === node.id);
      if (!row) {
        nodes.push(node);
        continue;
      }
      const matches = index.get(row.sourceView)?.get(caseId)?.decisionNodes.filter(candidate => candidate.id === row.nodeId);
      const candidate = matches?.[0];
      if (matches?.length !== 1 || !candidate ||
        candidate.questionVariantId !== row.questionVariantId || candidate.primaryConceptId !== row.conceptId ||
        !concepts.has(row.conceptId)) {
        retainLegacy(`missing exact accepted version/concept ${row.acceptanceId} in ${row.sourceView}`);
        invalid = true;
        break;
      }
      nodes.push(candidate);
    }
    if (invalid) continue;
    cases.push({
      ...header, decisionNodes: nodes,
      // Mixed accepted/fallback cases summarize the definitions actually used.
      learningSummary: nodes.length === 1 ? nodes[0]!.explanation : nodes.map(node => node.explanation).join(" "),
    });
  }
  // Preserve concepts used by prior frozen encounters and FSRS histories.
  return { ...catalog, cases };
}

