import { describe, expect, it } from "vitest";
import { BOARD_EXPANSION_CASES, SYNTHETIC_CLINICAL_RELEASE } from "@gamify-surgery/clinical-content";
import { createInitialGameState, createPatientPixelAppearance, deserializeGameState, gameReducer, getCurrentQuestion, serializeGameState, type GameState } from "../src";

function prepared(seed: string): GameState {
  const state = createInitialGameState(undefined, { campaignId: `campaign.board.${seed}`, campaignSeed: seed, createdAtRealMs: 0 });
  state.facilityLevel = 1;
  state.encounters = {};
  state.nextRoutineArrivalTick = Number.MAX_SAFE_INTEGER;
  state.rooms.push({ id: "room.board.examination", roomDefinitionId: "room.examination", x: 34, y: 26, orientation: 0, doorSide: "south", upgradeLevel: 1, cleanliness: 100 });
  state.doors.push({ id: "door.board.examination", roomId: "room.board.examination", side: "south", offset: 1, exterior: false });
  return state;
}
function ready(state: GameState, encounterId: string, prefix: string): GameState {
  let next = state;
  for (let attempt = 0; attempt < 1_000; attempt += 1) {
    if (getCurrentQuestion(next, encounterId)) return next;
    const encounter = next.encounters[encounterId]!;
    next = encounter.lifecycle === "waiting_unopened" && encounter.patientMovement === null
      ? gameReducer(next, { type: "OPEN_CHART", operationId: `${prefix}.open.${attempt}`, encounterId })
      : gameReducer(next, { type: "ADVANCE_TICK", operationId: `${prefix}.tick.${attempt}` });
  }
  throw new Error(`${encounterId} did not become ready`);
}
function correct(state: GameState, encounterId: string, operationId: string, reviewedAtMs: number): GameState {
  const question = getCurrentQuestion(state, encounterId)!;
  return gameReducer(state, { type: "SUBMIT_ANSWER", operationId, encounterId, decisionNodeId: question.node.id, answerChoiceId: question.node.answerChoices.find((choice) => choice.isCorrect)!.id, reviewedAtMs });
}
function ack(state: GameState, encounterId: string, operationId: string): GameState {
  const encounter = state.encounters[encounterId]!;
  return gameReducer(state, { type: "ACKNOWLEDGE_DECISION_FEEDBACK", operationId, encounterId, decisionNodeId: encounter.steps[encounter.currentNodeIndex]!.decisionNodeId });
}

// Current admission uses revised result prose; historical definitions are
// preserved separately. Keep the same concepts, due ticks and reducer checks.
const liveCases = BOARD_EXPANSION_CASES.map(source => SYNTHETIC_CLINICAL_RELEASE.cases.find(c => c.id === source.id)!);
describe("September 11 board-expansion production flows", () => {
  it.each(liveCases.map((clinicalCase, index) => [index, clinicalCase] as const))("runs case %s through its real gate with one review per concept", (index, clinicalCase) => {
      const encounterId = `encounter.board.${index}`;
      let state = prepared(`all-${index}`);
      state = gameReducer(state, { type: "ADMIT_PATIENT", operationId: `board.${index}.admit`, encounterId, caseId: clinicalCase.id, patientDisplayName: `Board Patient ${index}`, arrivalClass: "routine" });
      expect(state.operationReceipts[`board.${index}.admit`]?.status).toBe("applied");
      state = ready(state, encounterId, `board.${index}.first`);
      const first = getCurrentQuestion(state, encounterId)!;
      expect(first.node.primaryConceptId).toBe(clinicalCase.decisionNodes[0]!.primaryConceptId);
      state = correct(state, encounterId, `board.${index}.first.answer`, index + 1);
      if(clinicalCase.id==="case.asymptomatic-phpt.incidental-calcium"){
        // Manager-accepted G05 replaces this entire fresh encounter. The old
        // two-node gate is exercised by frozen snapshot/journal completion tests.
        expect(clinicalCase.decisionNodes).toHaveLength(1);
        expect(first.node.questionVariantId).toBe("question.asymptomatic-phpt.age-based-surgery.v1.r3");
        expect(clinicalCase.decisionNodes[0]!.resultGateAfter).toBeNull();
        expect(state.encounters[encounterId]!).toMatchObject({lifecycle:"resolved_summary_available",resolutionReason:"completed",pendingResult:null});
        expect(state.encounters[encounterId]!.answers).toHaveLength(1);
        expect(state.learningHistories[first.node.primaryConceptId]?.reviews).toHaveLength(1);
        expect(getCurrentQuestion(state,encounterId)).toBeNull();
        return;
      }
      expect(state.encounters[encounterId]!.steps[0]!.status).toBe("feedback_pending");
      state = ack(state, encounterId, `board.${index}.first.ack`);
      const pending = state.encounters[encounterId]!.pendingResult!;
      expect(pending).toMatchObject({ resultTypeId: clinicalCase.decisionNodes[0]!.resultGateAfter!.resultTypeId });
      expect(pending.dueTick).toBeGreaterThan(state.facilityTick);
      while (state.facilityTick < pending.dueTick) {
        expect(getCurrentQuestion(state, encounterId)).toBeNull();
        expect(state.encounters[encounterId]!.deliveredResultNarratives).toEqual([]);
        state = gameReducer(state, { type: "ADVANCE_TICK", operationId: `board.${index}.wait.${state.facilityTick}` });
      }
      state = ready(state, encounterId, `board.${index}.second`);
      expect(state.encounters[encounterId]!.deliveredResultNarratives).toContain(clinicalCase.decisionNodes[0]!.resultGateAfter!.resultNarrative);
      const second = getCurrentQuestion(state, encounterId)!;
      expect(second.node.primaryConceptId).toBe(clinicalCase.decisionNodes[1]!.primaryConceptId);
      state = correct(state, encounterId, `board.${index}.second.answer`, index + 10_000);
      expect(state.encounters[encounterId]!).toMatchObject({ lifecycle: "resolved_summary_available", resolutionReason: "completed" });
      expect(state.encounters[encounterId]!.pendingResult).toMatchObject({ deliveredAtTick: expect.any(Number) });
      expect(state.encounters[encounterId]!.pendingResult!.dueTick).toBeLessThanOrEqual(state.encounters[encounterId]!.pendingResult!.deliveredAtTick!);
      expect(getCurrentQuestion(state, encounterId)).toBeNull();
      expect(state.learningHistories[first.node.primaryConceptId]?.reviews).toHaveLength(1);
      expect(state.learningHistories[second.node.primaryConceptId]?.reviews).toHaveLength(1);
  });

  it("corrects forward after a wrong answer and preserves the pending frozen encounter across reload", () => {
    const clinicalCase = BOARD_EXPANSION_CASES[0]!;
    const encounterId = "encounter.board.persistence";
    let state = prepared("persistence");
    state = gameReducer(state, { type: "ADMIT_PATIENT", operationId: "board.persist.admit", encounterId, caseId: clinicalCase.id, patientDisplayName: "Persistent Patient", arrivalClass: "routine" });
    const frozen = state.encounters[encounterId]!.frozenCase;
    const appearance = state.encounters[encounterId]!.patientAppearance;
    expect(appearance).toEqual(createPatientPixelAppearance(state.campaignSeed, encounterId, frozen.prototypeDemographics!));
    state = ready(state, encounterId, "board.persist");
    const question = getCurrentQuestion(state, encounterId)!;
    const wrong = question.node.answerChoices.find((choice) => !choice.isCorrect)!;
    state = gameReducer(state, { type: "SUBMIT_ANSWER", operationId: "board.persist.answer", encounterId, decisionNodeId: question.node.id, answerChoiceId: wrong.id, reviewedAtMs: 99 });
    expect(state.encounters[encounterId]!.steps[0]!.answer).toMatchObject({ correct: false, correctedForward: true, ratingIntent: "Again" });
    state = ack(state, encounterId, "board.persist.ack");
    const pending = state.encounters[encounterId]!.pendingResult!;
    const restored = deserializeGameState(serializeGameState(state));
    expect(restored.encounters[encounterId]!.pendingResult).toEqual(pending);
    expect(restored.encounters[encounterId]!.frozenCase).toEqual(frozen);
    expect(restored.encounters[encounterId]!.patientAppearance).toEqual(appearance);
    expect(restored.encounters[encounterId]!.patientDisplayName).toBe("Persistent Patient");
  });
});

import { describe, expect, it } from "vitest";
import { BRIEF_EARLY_LEVELS_20260917_CASES } from "@gamify-surgery/clinical-content";
import {
  createInitialGameState,
  deserializeGameState,
  gameReducer,
  getCurrentQuestion,
  serializeGameState,
  type GameState,
} from "../src";

function prepared(seed: string, level: 0 | 1 | 2): GameState {
  const state = createInitialGameState(undefined, {
    campaignId: `campaign.brief-sept17.${seed}`,
    campaignSeed: seed,
    createdAtRealMs: 0,
  });
  state.facilityLevel = level;
  state.encounters = {};
  state.openChartEncounterId = null;
  state.attendedEncounterId = null;
  state.nextRoutineArrivalTick = Number.MAX_SAFE_INTEGER;
  state.rooms.push({
    id: "room.brief-sept17.examination",
    roomDefinitionId: "room.examination",
    x: 34,
    y: 26,
    orientation: 0,
    doorSide: "south",
    upgradeLevel: 1,
    cleanliness: 100,
  });
  state.doors.push({
    id: "door.brief-sept17.examination",
    roomId: "room.brief-sept17.examination",
    side: "south",
    offset: 1,
    exterior: false,
  });
  return state;
}

function ready(
  state: GameState,
  encounterId: string,
  operationPrefix: string,
): GameState {
  let next = state;
  for (let attempt = 0; attempt < 1500; attempt += 1) {
    if (getCurrentQuestion(next, encounterId)) {
      return next;
    }
    const encounter = next.encounters[encounterId];
    if (!encounter) {
      throw new Error(`${encounterId} disappeared before becoming ready`);
    }
    next =
      encounter.lifecycle === "waiting_unopened" &&
      encounter.patientMovement === null
        ? gameReducer(next, {
            type: "OPEN_CHART",
            operationId: `${operationPrefix}.open.${attempt}`,
            encounterId,
          })
        : gameReducer(next, {
            type: "ADVANCE_TICK",
            operationId: `${operationPrefix}.tick.${attempt}`,
          });
  }
  throw new Error(`${encounterId} did not become ready`);
}

function submit(
  state: GameState,
  encounterId: string,
  correct: boolean,
  operationId: string,
  reviewedAtMs: number,
): GameState {
  const question = getCurrentQuestion(state, encounterId);
  if (!question) {
    throw new Error(`${encounterId} has no current question`);
  }
  const choice = question.node.answerChoices.find(
    (item) => item.isCorrect === correct,
  );
  if (!choice) {
    throw new Error(
      `${question.node.id} has no ${correct ? "correct" : "incorrect"} choice`,
    );
  }
  return gameReducer(state, {
    type: "SUBMIT_ANSWER",
    operationId,
    encounterId,
    decisionNodeId: question.node.id,
    answerChoiceId: choice.id,
    reviewedAtMs,
  });
}

function acknowledge(
  state: GameState,
  encounterId: string,
  operationId: string,
): GameState {
  const encounter = state.encounters[encounterId];
  if (!encounter) {
    throw new Error(`${encounterId} is unavailable for feedback acknowledgement`);
  }
  const step = encounter.steps[encounter.currentNodeIndex];
  if (!step) {
    throw new Error(`${encounterId} has no current decision step`);
  }
  return gameReducer(state, {
    type: "ACKNOWLEDGE_DECISION_FEEDBACK",
    operationId,
    encounterId,
    decisionNodeId: step.decisionNodeId,
  });
}

function advanceUntilResult(
  state: GameState,
  encounterId: string,
  operationPrefix: string,
): GameState {
  let next = state;
  const pending = next.encounters[encounterId]?.pendingResult;
  if (!pending) {
    throw new Error(`${encounterId} did not schedule a result`);
  }
  while (next.facilityTick < pending.dueTick) {
    expect(getCurrentQuestion(next, encounterId)).toBeNull();
    expect(next.encounters[encounterId]?.deliveredResultNarratives).toEqual([]);
    next = gameReducer(next, {
      type: "ADVANCE_TICK",
      operationId: `${operationPrefix}.${next.facilityTick}`,
    });
  }
  return next;
}

describe("September 17 brief early-level production flows", () => {
  it("contains the expected single-step and gated case mix", () => {
    const gated = BRIEF_EARLY_LEVELS_20260917_CASES.filter(
      (clinicalCase) => clinicalCase.decisionNodes.length === 2,
    );
    const single = BRIEF_EARLY_LEVELS_20260917_CASES.filter(
      (clinicalCase) => clinicalCase.decisionNodes.length === 1,
    );
    expect(BRIEF_EARLY_LEVELS_20260917_CASES).toHaveLength(48);
    expect(gated).toHaveLength(32);
    expect(single).toHaveLength(16);
    expect(
      gated.every(
        (clinicalCase) =>
          clinicalCase.decisionNodes[0]?.resultGateAfter !== null,
      ),
    ).toBe(true);
  });

  it.each(
    BRIEF_EARLY_LEVELS_20260917_CASES.map(
      (clinicalCase, index) => [index, clinicalCase] as const,
    ),
  )(
    "runs case %s through every authored node with one FSRS review",
    (index, clinicalCase) => {
      const encounterId = `encounter.brief-sept17.${index}`;
      const prefix = `brief-sept17.${index}`;
      let state = prepared(
        `all-${index}`,
        clinicalCase.earliestFacilityStage,
      );
      state = gameReducer(state, {
        type: "ADMIT_PATIENT",
        operationId: `${prefix}.admit`,
        encounterId,
        caseId: clinicalCase.id,
        patientDisplayName: `Brief Patient ${index}`,
        arrivalClass: "routine",
      });
      expect(state.operationReceipts[`${prefix}.admit`]?.status).toBe("applied");

      state = ready(state, encounterId, `${prefix}.first`);
      const first = getCurrentQuestion(state, encounterId);
      expect(first?.node.id).toBe(clinicalCase.decisionNodes[0]?.id);
      state = submit(
        state,
        encounterId,
        true,
        `${prefix}.first.answer`,
        index + 1,
      );
      expect(
        state.learningHistories[first!.node.primaryConceptId]?.reviews,
      ).toHaveLength(1);

      if (clinicalCase.decisionNodes.length === 1) {
        expect(state.encounters[encounterId]).toMatchObject({
          lifecycle: "resolved_summary_available",
          resolutionReason: "completed",
          pendingResult: null,
        });
        return;
      }

      state = acknowledge(
        state,
        encounterId,
        `${prefix}.first.acknowledge`,
      );
      const gate = clinicalCase.decisionNodes[0]!.resultGateAfter;
      expect(gate).not.toBeNull();
      const pending = state.encounters[encounterId]?.pendingResult;
      expect(pending).toMatchObject({ resultTypeId: gate!.resultTypeId });
      expect(pending!.dueTick).toBeGreaterThan(state.facilityTick);

      state = advanceUntilResult(state, encounterId, `${prefix}.wait`);
      state = ready(state, encounterId, `${prefix}.second`);
      expect(
        state.encounters[encounterId]?.deliveredResultNarratives,
      ).toContain(gate!.resultNarrative);

      const second = getCurrentQuestion(state, encounterId);
      expect(second?.node.id).toBe(clinicalCase.decisionNodes[1]?.id);
      state = submit(
        state,
        encounterId,
        true,
        `${prefix}.second.answer`,
        index + 10_000,
      );
      expect(state.encounters[encounterId]).toMatchObject({
        lifecycle: "resolved_summary_available",
        resolutionReason: "completed",
      });
      expect(
        state.encounters[encounterId]?.pendingResult?.deliveredAtTick,
      ).toBe(pending!.dueTick);
      expect(
        state.learningHistories[second!.node.primaryConceptId]?.reviews,
      ).toHaveLength(1);
    },
  );

  it("rejects a case before its authored facility stage", () => {
    const clinicalCase = BRIEF_EARLY_LEVELS_20260917_CASES.find(
      (item) => item.earliestFacilityStage === 2,
    );
    if (!clinicalCase) {
      throw new Error("Expected at least one Level 2 case");
    }
    const state = gameReducer(prepared("stage-rejection", 0), {
      type: "ADMIT_PATIENT",
      operationId: "brief-sept17.stage.reject",
      encounterId: "encounter.brief-sept17.stage",
      caseId: clinicalCase.id,
      patientDisplayName: "Stage Patient",
      arrivalClass: "routine",
    });
    expect(state.operationReceipts["brief-sept17.stage.reject"]).toMatchObject({
      status: "rejected",
    });
    expect(state.encounters["encounter.brief-sept17.stage"]).toBeUndefined();
  });

  it("preserves corrected-forward gated state and finishes after reload", () => {
    const clinicalCase = BRIEF_EARLY_LEVELS_20260917_CASES.find(
      (item) =>
        item.decisionNodes.length === 2 &&
        item.decisionNodes[0]?.resultGateAfter !== null,
    );
    if (!clinicalCase) {
      throw new Error("Expected at least one gated case");
    }

    const encounterId = "encounter.brief-sept17.persist";
    let state = prepared(
      "corrected-forward-persistence",
      clinicalCase.earliestFacilityStage,
    );
    state = gameReducer(state, {
      type: "ADMIT_PATIENT",
      operationId: "brief-sept17.persist.admit",
      encounterId,
      caseId: clinicalCase.id,
      patientDisplayName: "Persistent Patient",
      arrivalClass: "routine",
    });
    state = ready(state, encounterId, "brief-sept17.persist.first");

    const first = getCurrentQuestion(state, encounterId);
    if (!first) {
      throw new Error("Expected the first persisted question");
    }
    const choiceOrder = first.node.answerChoices.map((choice) => choice.id);
    state = submit(
      state,
      encounterId,
      false,
      "brief-sept17.persist.wrong-answer",
      99,
    );
    expect(state.encounters[encounterId]?.steps[0]?.answer).toMatchObject({
      correct: false,
      correctedForward: true,
      ratingIntent: "Again",
    });
    expect(
      state.learningHistories[first.node.primaryConceptId]?.reviews,
    ).toHaveLength(1);

    state = acknowledge(
      state,
      encounterId,
      "brief-sept17.persist.acknowledge",
    );
    const pending = state.encounters[encounterId]?.pendingResult;
    if (!pending) {
      throw new Error("Expected corrected-forward answer to schedule a result");
    }

    let restored = deserializeGameState(serializeGameState(state));
    expect(restored.encounters[encounterId]?.pendingResult).toEqual(pending);
    expect(restored.encounters[encounterId]?.pendingResult?.dueTick).toBe(
      pending.dueTick,
    );
    expect(restored.encounters[encounterId]?.patientDisplayName).toBe(
      "Persistent Patient",
    );
    expect(restored.encounters[encounterId]?.frozenCase).toEqual(
      state.encounters[encounterId]?.frozenCase,
    );
    expect(
      restored.encounters[
        encounterId
      ]?.frozenCase.decisionNodes[0]?.answerChoices.map((choice) => choice.id),
    ).toEqual(choiceOrder);
    expect(
      restored.learningHistories[first.node.primaryConceptId]?.reviews,
    ).toHaveLength(1);

    restored = advanceUntilResult(
      restored,
      encounterId,
      "brief-sept17.persist.wait",
    );
    restored = ready(
      restored,
      encounterId,
      "brief-sept17.persist.second",
    );
    const gate = clinicalCase.decisionNodes[0]!.resultGateAfter!;
    expect(
      restored.encounters[encounterId]?.deliveredResultNarratives,
    ).toContain(gate.resultNarrative);

    const second = getCurrentQuestion(restored, encounterId);
    if (!second) {
      throw new Error("Expected the second persisted question");
    }
    expect(second.node.id).toBe(clinicalCase.decisionNodes[1]?.id);
    restored = submit(
      restored,
      encounterId,
      true,
      "brief-sept17.persist.second.answer",
      10_099,
    );
    expect(restored.encounters[encounterId]).toMatchObject({
      lifecycle: "resolved_summary_available",
      resolutionReason: "completed",
    });
    expect(
      restored.encounters[encounterId]?.pendingResult?.deliveredAtTick,
    ).toBe(pending.dueTick);
    expect(
      restored.learningHistories[second.node.primaryConceptId]?.reviews,
    ).toHaveLength(1);
    expect(
      restored.learningHistories[first.node.primaryConceptId]?.reviews,
    ).toHaveLength(1);
  });
});

import { SYNTHETIC_CLINICAL_RELEASE } from "@gamify-surgery/clinical-content";
import { describe, expect, it } from "vitest";
import { EXACT_DIAGNOSTIC_RESULT_RECORDS, getDiagnosticResultDisposition } from "../src/diagnostic-result-dispositions";
import type { EncounterState } from "../src";

describe("exact frozen endoscopy result contracts", () => {
  it("binds every operational annotation to an active exact choice and profile, including distractors", () => {
    const keys = new Set<string>();
    for (const record of EXACT_DIAGNOSTIC_RESULT_RECORDS) {
      const clinicalCase = SYNTHETIC_CLINICAL_RELEASE.cases.find((candidate) => candidate.id === record.caseId);
      const node = clinicalCase?.decisionNodes.find((candidate) => candidate.id === record.nodeId && candidate.questionVariantId === record.questionVariantId);
      const key = `${record.caseId}|${record.nodeId}|${record.choiceId}`;
      expect(keys.has(key), key).toBe(false); keys.add(key);
      expect(node, key).toBeDefined();
      const encounter = { frozenCase: clinicalCase } as EncounterState;
      if (record.result) expect(getDiagnosticResultDisposition(encounter, node!, record.choiceId), key).toEqual(record.result);
      for (const [componentId, result] of Object.entries(record.components ?? {})) {
        expect(getDiagnosticResultDisposition(encounter, node!, record.choiceId, componentId), key).toEqual(result);
      }
    }
  });

  it("separates a visual update with pending histology from a returned biopsy result", () => {
    const selected = (caseId: string, index: number, choiceId: string) => {
      const clinicalCase = SYNTHETIC_CLINICAL_RELEASE.cases.find((candidate) => candidate.id === caseId)!;
      return getDiagnosticResultDisposition({ frozenCase: clinicalCase } as EncounterState, clinicalCase.decisionNodes[index]!, choiceId);
    };
    expect(selected("case.recovered-diverticulitis.drained-abscess", 0, "colonoscopy_1")).toEqual({ specimenCollected: false, resultKind: "visual" });
    expect(selected("case.esophageal-dysphagia.bread-sticking", 0, "egd_1")).toEqual({ specimenCollected: true, resultKind: "pathology" });
    expect(selected("case.colorectal.routine-screen", 0, "colonoscopy_1")).toEqual({ specimenCollected: true, resultKind: "visual" });
    expect(selected("case.celiac.chronic-diarrhea", 1, "colonoscopy_1")).toEqual({ specimenCollected: true, resultKind: "pathology" });
  });

  it("does not infer specimen collection from altered labels or new question versions", () => {
    const original = SYNTHETIC_CLINICAL_RELEASE.cases.find((candidate) => candidate.id === "case.esophageal-dysphagia.bread-sticking")!;
    const clinicalCase = JSON.parse(JSON.stringify(original)) as typeof original;
    const node = clinicalCase.decisionNodes[0]!;
    const encounter = { frozenCase: clinicalCase } as EncounterState;
    node.answerChoices.find((choice) => choice.id === "egd_1")!.label = "EGD";
    expect(getDiagnosticResultDisposition(encounter, node, "egd_1")).toBeNull();
    node.answerChoices.find((choice) => choice.id === "egd_1")!.label = "EGD with esophageal biopsies";
    node.questionVariantId += ".future";
    expect(getDiagnosticResultDisposition(encounter, node, "egd_1")).toBeNull();
  });
});
